let plannerUnit = 1;
let plannerWeek = '1';
function plannerLessons(unit, week) {
  const e = escapeHtml;
  return `<section class="planner-week"><div class="planner-week-heading"><div><p class="eyebrow">WEEK ${week.week} · LESSONS ${(week.week - 1) * 4 + 1}–${week.week * 4}</p><h2>${e(week.title)}</h2></div><span class="pill">4 lessons</span></div><div class="lesson-plan-grid">${week.lessons.map(lesson => `<article class="lesson-plan"><div class="lesson-plan-top"><strong>Lesson ${lesson.lesson}</strong><span class="lesson-kind ${lesson.kind === 'Project workshop' ? 'workshop' : ''}">${e(lesson.kind)}</span></div><h3>${e(lesson.title)}</h3><p class="lesson-objective">${e(lesson.objective)}</p><h4>Teach &amp; do</h4><p>${e(lesson.activity)}</p><h4>Check before moving on</h4><p>${e(lesson.check)}</p>${lesson.checkExpected ? `<details class="lesson-check-guide"><summary>Expected reasoning &amp; next teaching step</summary><p><strong>Expected:</strong> ${e(lesson.checkExpected)}</p><p><strong>If not yet secure:</strong> ${e(lesson.checkReteach)}</p></details>` : ''}<div class="lesson-plan-links"><a class="button secondary" href="#${e(lesson.chapter)}">Open chapter</a>${lesson.workbook ? `<a class="button secondary" href="${e(lesson.workbook)}" download>Workbook</a>` : ''}${lesson.gameProjectYear ? `<a class="button secondary" href="${e(lesson.gameContract)}" download>Shared game requirements</a><a class="button secondary" href="${e(lesson.gamePack)}" download>Five-theme project pack</a><p>Requirement focus: ${e(lesson.gameRequirements)}</p>` : ''}${lesson.pygamePractice ? `<a class="button" href="${e(lesson.pygameBridge)}">Pygame teaching &amp; practice</a><a class="button secondary" href="pygame/pygame-teaching-pack.zip" download>Pygame teaching pack</a><p>55 minutes: 5 retrieve, 10 model, 15 guided, 15 independent, 5 check, 5 record. Existing slides cover the original Python strand; use the linked lab for Pygame.</p>` : ''}${plannerSlideLinks(unit, week, lesson)}</div></article>`).join('')}</div></section>`;
}
function plannerContent() {
  const unit = teachingSchedule.find(item => item.unit === plannerUnit);
  const weeks = plannerWeek === 'all' ? unit.weeks : unit.weeks.filter(week => String(week.week) === plannerWeek);
  return `<div class="planner-unit-heading"><div><p class="eyebrow">YEAR ${unit.year} · UNIT ${unit.unit}</p><h2>${escapeHtml(unit.title)}</h2></div><div class="planner-facts"><span><strong>64</strong> teaching lessons</span><span><strong>${unit.projectLessons}</strong> embedded project lessons</span><span><strong>17–18</strong> exam weeks</span></div></div><div class="week-strip" aria-label="Choose teaching week">${unit.weeks.map(week => `<button type="button" class="week-chip" data-planner-week="${week.week}" aria-pressed="${plannerWeek === String(week.week)}"><span>Week</span> ${week.week}</button>`).join('')}</div>${weeks.map(week => plannerWeek === 'all' ? `<details class="planner-week-disclosure" open><summary>Week ${week.week} · ${escapeHtml(week.title)}</summary>${plannerLessons(unit, week)}</details>` : plannerLessons(unit, week)).join('')}<section class="exam-block"><span class="pill">EXAM BLOCK</span><h2>Weeks 17–18</h2><p>School examinations. No new teaching chapters, extra project lessons or project deadlines. Confirm the school calendar; the external Year 12 ATAR timetable is separate.</p></section>`;
}
function teacherPlannerPage() {
  return `<article class="teacher-planner"><p class="eyebrow">TEACHER PLANNER · UNITS 1–4</p><h1>A clear plan.<br>Every lesson.</h1><p class="lede">Choose your unit and week to see what to teach, what students do and what to check before moving on.</p><p><a class="button secondary" href="resources/">Lesson resource hub</a> <a class="button secondary" href="sql/">SQL pathway &amp; readiness checks</a> · <a href="activities/programming-foundations/">Programming foundations: eight printable activities</a> <a class="button secondary" href="pygame/">Pygame preparation: lessons, code and readiness checks</a> <a class="button secondary" href="project-trial/">Project workload trial &amp; moderation</a> <a class="button secondary" href="curriculum/">2027 syllabus map &amp; gaps</a></p><div class="planner-toolbar no-print"><div class="unit-picker" aria-label="Choose unit">${teachingSchedule.map(unit => `<button type="button" data-planner-unit="${unit.unit}" aria-pressed="${plannerUnit === unit.unit}"><small>Year ${unit.year}</small>Unit ${unit.unit}</button>`).join('')}</div><div class="planner-tools"><label for="planner-week-select">Show</label><select id="planner-week-select">${Array.from({ length: 16 }, (_, i) => `<option value="${i + 1}" ${plannerWeek === String(i + 1) ? 'selected' : ''}>Week ${i + 1}</option>`).join('')}<option value="all" ${plannerWeek === 'all' ? 'selected' : ''}>Whole semester</option></select><a class="button secondary" href="teaching-lessons.csv" download>Download 256-lesson plan</a><a class="button secondary" href="lesson-exit-checks.md" download>Exit questions &amp; teacher guidance</a><a href="teaching-sequence.md" download>Outline &amp; assessment assumptions</a></div></div><p class="planner-status" role="status" aria-live="polite">Unit ${plannerUnit} · ${plannerWeek === 'all' ? 'Whole semester' : 'Week ' + plannerWeek}</p><div id="planner-content">${plannerContent()}</div><details class="planner-guidance"><summary>Planning assumptions and how to use this sequence</summary><p>Four lessons a week for 16 teaching weeks, followed by two blocked exam weeks. Week numbers reset each semester. The project allocations are already included: Unit 1 has 10 lessons, Unit 2 has 14, Unit 3 has 12 and Unit 4 has 16. Unit 4 also has four foundation lessons before its project launch.</p><p>Start each lesson with a short retrieval prompt from previous learning. Model unfamiliar work, allow guided then independent practice, and use the check to decide whether to move on or reteach. Checkpoints are formative; assessment slots use the school’s adopted conditions and marking. Do not add an extra task merely because a practice sample is available.</p><p>Use synthetic data and prepare the linked chapter/workbook before class. Python editor for programming; a disposable SQLite database for SQL. Reference solutions are teaching examples; independent learner evidence remains necessary.</p><p>This is a proposed teaching plan, not a prescribed SCSA outline or certified alignment. Actual period length, event losses, source currency and school assessment requirements need teacher review. At 55 minutes, 64 lessons provide 58h 40m; at 50 minutes they provide 53h 20m. Confirm contact hours locally.</p></details></article>`;
}
function updateTeacherPlanner() {
  const content = document.getElementById('planner-content');
  if (!content) return;
  content.innerHTML = plannerContent();
  document.querySelectorAll('[data-planner-unit]').forEach(button => button.setAttribute('aria-pressed', String(Number(button.dataset.plannerUnit) === plannerUnit)));
  document.getElementById('planner-week-select').value = plannerWeek;
  document.querySelector('.planner-status').textContent = `Unit ${plannerUnit} · ${plannerWeek === 'all' ? 'Whole semester' : 'Week ' + plannerWeek}`;
}
document.addEventListener('click', event => {
  const unit = event.target.closest('[data-planner-unit]');
  const week = event.target.closest('[data-planner-week]');
  if (unit) { plannerUnit = Number(unit.dataset.plannerUnit); plannerWeek = '1'; updateTeacherPlanner(); }
  if (week) { plannerWeek = week.dataset.plannerWeek; updateTeacherPlanner(); document.getElementById('planner-week-select').focus(); }
});
document.addEventListener('change', event => {
  if (event.target.id === 'planner-week-select') { plannerWeek = event.target.value; updateTeacherPlanner(); }
});

function plannerSlideLinks(unit, week, lesson) {
  if (lesson.gameProjectYear) return '<p>Updated Pygame project slides are pending (A06). Use the aligned chapter and workbook for this workshop.</p>';
  const key = `u${unit.unit}-w${String(week.week).padStart(2, '0')}-l${String(lesson.lesson).padStart(2, '0')}`;
  if (!lessonSlideResources[key]) return '';
  return `<a class="button" href="slides/?lesson=${key}">Present slides</a><a class="button secondary" href="slides/${key}.pptx" download>Editable PowerPoint</a><a class="button secondary" href="slides/notes/${key}.html">Teacher notes</a>`;
}
